init(_props, cx) {
    this.spiderFeedTimer = cx.timer;
    if (spiderProps().moveMenu) { initMoveMenu(this, cx); return; }
    if (props()?.sortMenu) return;
/* spider-look:feed-lifecycle */    this.folded = new Set();
    this.spiderFeeds = [];
    this.expandedConsoles = new Set();
    const root = spiderProps().feedRoot;
    if (root) {
      const watchFeeds = cx => {
        if (this.spiderWatching) return;
        this.spiderWatching = true; this.spiderWatchFailed = false;
        cx.spawn(async cx => {
          try {
            let next = watchFolder(root + "/sessions"); this.spiderWatch = next; next.catch(() => {});
            await this.reloadSpiderFeeds(); cx.notify();
            for (;;) {
              await next;
              if (this.spiderClosed) { next.cancel?.(); return; }
              next.cancel?.();
              next = watchFolder(root + "/sessions"); this.spiderWatch = next; next.catch(() => {});
              await this.reloadSpiderFeeds(); cx.notify();
            }
          } catch { this.spiderWatchFailed = true; this.spiderFeedError = "Feed watch unavailable; retrying"; cx.notify(); }
          finally { this.spiderWatching = false; }
        });
      };
      watchFeeds(cx);
      cx.timer.every(FEED_REFRESH_MS, cx => {
        if (this.spiderClosed || this.spiderLoading) return;
        if (this.spiderWatchFailed) watchFeeds(cx);
        else cx.spawn(async cx => { await this.reloadSpiderFeeds(); cx.notify(); });
      });
    }
    // Each agent's last state and when it changed (ms), kept across restarts.
    this.changed = JSON.parse(localStorage.getItem("changed") ?? "{}");
    this.pendingPins = JSON.parse(localStorage.getItem("pins") ?? "[]");
    if (!this.pendingPins.length) localStorage.removeItem("pins");
    this.migratingPins = new Set();
    cx.timer.every(30000, (cx) => cx.notify());
  }

