/* spider-look:rail-render */    const collapsed = narrow();
    {
      const sidebar = find(layout(), "sidebar");
      const ids = ["brand", "agents", "sidebar-footer"];
      const key = "spider.sidebar.rail";
      let state = null;
      try { state = JSON.parse(localStorage.getItem(key) ?? "null"); } catch {}
      if (!state || typeof state.folded !== "boolean" || !Array.isArray(state.userHidden)) state = null;
      if (sidebar && collapsed) {
        if (!state || !state.folded) {
          // Missing state may be a reset after a crash. Treat hidden blocks as leftovers.
          const userHidden = state ? ids.filter(id => find(sidebar, id)?.hidden) : [];
          state = { folded: true, userHidden };
          localStorage.setItem(key, JSON.stringify(state));
        }
        for (const id of ids) { const node = find(sidebar, id); if (node && !node.hidden) run("layout.hide", { id }); }
      } else if (sidebar) {
        // When wide, restore hidden blocks except those recorded as user-hidden before folding.
        // Without a record, restore all three because the stock layout shows them.
        for (const id of ids) { const node = find(sidebar, id); if (node?.hidden && !state?.userHidden.includes(id)) run("layout.show", { id }); }
        if (!state || state.folded) localStorage.setItem(key, JSON.stringify({ folded: false, userHidden: state?.userHidden ?? [] }));
      }
    }
    if (collapsed) {
      const rows = this.ordered(true);
      const machines = [null, ...[...new Set(rows.map(r => r.w.machine).filter(Boolean))].sort()];
      const items = [];
      for (const machine of machines) {
        const mine = rows.filter(r => (r.w.machine ?? null) === machine);
        if (!mine.length) continue;
        if (items.length) items.push(div().h(6).flex_none());
        items.push(...mine.map(r => this.compact(r, t)));
