tree(all, addr, lead = []) {
    const contract = spiderProps().labelContract;
    if (!contract) return [];
    const rows = this.projectChildren(all, addr);
    const hidden = new Set();
    const selected = selectAgentChildren(rows, [...(this.expandedConsoles ?? [])]).filter(row => {
      if (hidden.has(row.parentKey) || this.folded.has(row.parentKey)) { hidden.add(row.key); return false; }
      return true;
    });
    const byKey = new Map(rows.map(row => [row.key, row])), live = new Set();
    for (const row of rows) if (!row.retained) {
      for (let current = row; current && !live.has(current.key); current = byKey.get(current.parentKey)) live.add(current.key);
    }
    (this.spiderHiddenFinished ??= new Map()).set(addr, selected.filter(row => !live.has(row.key)).length);
    const visible = this.spiderShowFinished?.has(addr) ? selected : selected.filter(row => live.has(row.key));
    const remaining = new Map(), stems = [];
    if (this.spiderHiddenFinished.get(addr) > 0) remaining.set(null, 1);
    for (const row of visible) remaining.set(row.parentKey, (remaining.get(row.parentKey) ?? 0) + 1);
    return visible.map(row => {
      const siblings = remaining.get(row.parentKey) - 1; remaining.set(row.parentKey, siblings);
      const lines = [...lead, ...stems.slice(0, row.depth), siblings ? "├" : "└"];
      stems[row.depth] = siblings ? "│" : ""; stems.length = row.depth + 1;
      const hasChildren = rows.some(child => child.parentKey === row.key);
      const open = row.kind === "console" ? this.expandedConsoles?.has(row.key) : !this.folded.has(row.key);
      return { t: { ...row.terminal, ...row, spider: row.kind !== "native" }, lines, hasChildren, open };
    });
  }

