      try { state = JSON.parse(localStorage.getItem(key) ?? "null"); } catch {}
      if (!state || typeof state.folded !== "boolean" || !Array.isArray(state.userHidden)) state = null;
      if (sidebar && collapsed) {
        if (!state || !state.folded) {
          // Missing state may be a reset after a crash. Treat hidden blocks as leftovers.
          const userHidden = state ? ids.filter(id => find(sidebar, id)?.hidden) : [];
          state = { folded: true, userHidden };
          localStorage.setItem(key, JSON.stringify(state));
        }
        for (const id of ids) { const node = find(sidebar, id); if (node && !node.hidden) run("layout.hide", { id }); }
      } else if (sidebar) {
        // When wide, restore hidden blocks except those recorded as user-hidden before folding.
        // Without a record, restore all three because the stock layout shows them.
        for (const id of ids) { const node = find(sidebar, id); if (node?.hidden && !state?.userHidden.includes(id)) run("layout.show", { id }); }
        if (!state || state.folded) localStorage.setItem(key, JSON.stringify({ folded: false, userHidden: state?.userHidden ?? [] }));
      }
    }
    if (collapsed) {
      const rows = this.ordered(true);
      const machines = [null, ...[...new Set(rows.map(r => r.w.machine).filter(Boolean))].sort()];
      const items = [];
      for (const machine of machines) {
        const mine = rows.filter(r => (r.w.machine ?? null) === machine);
        if (!mine.length) continue;
        if (items.length) items.push(div().h(6).flex_none());
        items.push(...mine.map(r => this.compact(r, t)));
      }
      const expand = div().id("collapse").size(32).flex_none().flex().items_center().justify_center().rounded(8).text_size(13).text_color(t.dim)
        .hover(s => s.bg(t.hover).text_color(t.foreground)).cursor_pointer().tooltip("Expand sidebar")
        .on_click(() => { setShared("sidebar.collapsed", false); run("layout.resize", { id: "sidebar", px: shared("sidebar.width") ?? 268 }); }).child(image("frame/welcome/herdr.png").size(20).rounded(5));
      return v_flex().size_full().min_h(0).bg(t.chrome).items_center().gap(8).pl(8).pt(7)
        .child(expand)
        .child(v_flex().relative().w_full().flex_1().min_h(0)
          .child(v_flex().id("rail-spaces").w_full().h_full().items_center().gap(4).overflow_y_scroll().children(items))
          .child(Scrollbar.vertical("rail-spaces").absolute().inset_0().mode("scrolling")))
        .child(div().id("rail-settings").size(32).flex_none().flex().items_center().justify_center().rounded(8).mb(6).text_color(t.muted)
          .hover(s => s.bg(t.hover).text_color(t.foreground)).cursor_pointer().tooltip("Settings")
          .on_click(() => run("app.settings")).child(svg("mods/workspace-chrome/settings.svg").size(14)));
    }
    const palette = ["ansi6", "ansi3", "ansi4", "ansi5", "ansi2", "ansi1"];
    const sp = spaces();
    const ids = new Set(sp.map(p => p.id));
    const kept = Object.fromEntries(Object.entries(shared("space.colors") ?? {}).filter(([id]) => ids.has(id)));
    let changed = Object.keys(kept).length !== Object.keys(shared("space.colors") ?? {}).length;
    for (const p of sp) {
      if (kept[p.id] || p.name === "~") continue;
      const uses = c => Object.values(kept).filter(v => v === c).length;
      kept[p.id] = palette.reduce((best, c) => uses(c) < uses(best) ? c : best);
      changed = true;
    }
    if (changed) setShared("space.colors", kept);
    const list = this.grouped(t, collapsed);
    // Bring the active space into view when it, or its place in the list, changes; a row already in view stays put.
    const active = sp.find(p => p.active)?.id;
    if (active !== this.revealed || this.activeAt !== this.revealedAt) {
      this.revealed = active;
      this.revealedAt = this.activeAt;
      if (this.activeAt >= 0) this.scroll.scroll_to_item(this.activeAt);
    }
    return v_flex().size_full().min_h(0).bg(t.chrome).text_size(13)
      .child(h_flex().h(31).pl(16).pr(10).items_center().justify_between().text_size(11.5).text_color(t.dim)
        .when(collapsed, el => el.pl(0).pr(0).justify_center())
        .when(!collapsed, el => el.child("Spaces"))
        .child(div().id("space-new").size(26).flex_none().flex().items_center().justify_center().rounded(6).hover(s => s.bg(t.hover).text_color(t.foreground))
          .on_click(() => run("space.new")).child(svg("mods/workspace-chrome/plus.svg").size(14))))
      .child(v_flex().flex_1().min_h(0).px(collapsed ? 0 : 8).pb(14).overflow_y_scrollbar().mode("always").track_scroll(this.scroll)
        // A block above (another mod's) growing, or the window resizing, shrinks this list and can push the active space out.
        .on_size_change((_size, cx) => { if (this.activeAt >= 0) { this.scroll.scroll_to_item(this.activeAt); cx.notify(); } })
        .on_mouse_up("left", (_e, cx) => { this.pressed = null; cx.notify(); })
        .children(list));
  }

